import java.util.List;

public class LabeledGraphTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String show(List<?> list) {
        return list == null ? "null" : list.toString();
    }

    public static void main(String[] args) {
        LabeledGraph<String> g = new LabeledGraph<>();
        g.addEdge("a", "b");
        g.addEdge("a", "c");
        g.addEdge("b", "d");
        g.addEdge("c", "d");
        g.addEdge("a", "b");
        try {
            check("nodesSorted", "[a, b, c, d]", show(g.nodesSorted()));
            check("shortestPath(a, d) prefers b", "[a, b, d]", show(g.shortestPath("a", "d")));
            check("shortestPath(a, a)", "[a]", show(g.shortestPath("a", "a")));
            check("no path backwards", "[]", show(g.shortestPath("d", "a")));
            check("unknown node", "[]", show(g.shortestPath("a", "zz")));
            check("acyclic graph", false, g.hasCycle());
        } catch (RuntimeException e) {
            System.out.println("FAIL  string graph -- expected results but got "
                    + e.getClass().getSimpleName());
            failures++;
        }

        LabeledGraph<String> longer = new LabeledGraph<>();
        longer.addEdge("start", "mid");
        longer.addEdge("mid", "far");
        longer.addEdge("far", "end");
        longer.addEdge("start", "shortcut");
        longer.addEdge("shortcut", "end");
        try {
            check("shortest by edge count, not by name",
                    "[start, shortcut, end]", show(longer.shortestPath("start", "end")));
        } catch (RuntimeException e) {
            System.out.println("FAIL  shortcut graph -- " + e.getClass().getSimpleName());
            failures++;
        }

        LabeledGraph<Integer> numbers = new LabeledGraph<>();
        numbers.addEdge(3, 1);
        numbers.addEdge(1, 2);
        numbers.addEdge(2, 3);
        try {
            check("works with Integer labels", "[1, 2, 3]", show(numbers.nodesSorted()));
            check("cycle detected", true, numbers.hasCycle());
            check("path around the cycle", "[3, 1, 2]", show(numbers.shortestPath(3, 2)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  integer graph -- " + e.getClass().getSimpleName());
            failures++;
        }

        LabeledGraph<String> loop = new LabeledGraph<>();
        loop.addEdge("x", "x");
        try {
            check("self loop is a cycle", true, loop.hasCycle());
        } catch (RuntimeException e) {
            System.out.println("FAIL  self loop -- " + e.getClass().getSimpleName());
            failures++;
        }

        LabeledGraph<String> empty = new LabeledGraph<>();
        try {
            check("empty graph has no cycle", false, empty.hasCycle());
            check("empty graph has no nodes", "[]", show(empty.nodesSorted()));
        } catch (RuntimeException e) {
            System.out.println("FAIL  empty graph -- " + e.getClass().getSimpleName());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

