import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class LabeledGraph<T extends Comparable<T>> {

    private final Map<T, TreeSet<T>> edges = new TreeMap<>();

    public void addEdge(T from, T to) {
        edges.computeIfAbsent(from, k -> new TreeSet<>()).add(to);
        edges.computeIfAbsent(to, k -> new TreeSet<>());
    }

    public List<T> nodesSorted() {
        return new ArrayList<>(edges.keySet());
    }

    public List<T> shortestPath(T from, T to) {
        List<T> path = new ArrayList<>();
        if (!edges.containsKey(from) || !edges.containsKey(to)) {
            return path;
        }
        Map<T, T> cameFrom = new HashMap<>();
        Set<T> seen = new HashSet<>();
        Deque<T> queue = new ArrayDeque<>();
        seen.add(from);
        queue.add(from);
        boolean found = from.equals(to);
        while (!queue.isEmpty() && !found) {
            T current = queue.removeFirst();
            for (T next : edges.get(current)) {
                if (seen.add(next)) {
                    cameFrom.put(next, current);
                    if (next.equals(to)) {
                        found = true;
                        break;
                    }
                    queue.addLast(next);
                }
            }
        }
        if (!found) {
            return path;
        }
        T step = to;
        while (step != null) {
            path.add(step);
            step = step.equals(from) ? null : cameFrom.get(step);
        }
        Collections.reverse(path);
        return path;
    }

    public boolean hasCycle() {
        Set<T> finished = new HashSet<>();
        Set<T> onStack = new HashSet<>();
        for (T node : edges.keySet()) {
            if (!finished.contains(node) && visit(node, finished, onStack)) {
                return true;
            }
        }
        return false;
    }

    private boolean visit(T node, Set<T> finished, Set<T> onStack) {
        onStack.add(node);
        for (T next : edges.get(node)) {
            if (onStack.contains(next)) {
                return true;
            }
            if (!finished.contains(next) && visit(next, finished, onStack)) {
                return true;
            }
        }
        onStack.remove(node);
        finished.add(node);
        return false;
    }
}
